using System.Security.Claims;using Kaluz.Web.Models;using Kaluz.Web.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;
namespace Kaluz.Web.Controllers;
[Authorize(Roles="Administrador,Vendedora")]public class VentasController(Db db,KaluzService svc):Controller{
 int U=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 public IActionResult Index(){ViewBag.Rows=db.List("SELECT TOP 150 v.IdVenta,v.NumeroTicket,v.Fecha,v.Total,v.Estado,u.NombreCompleto,mp.Nombre AS Metodo FROM Venta v JOIN Usuario u ON u.IdUsuario=v.IdUsuario JOIN MetodoPago mp ON mp.IdMetodoPago=v.IdMetodoPago ORDER BY v.IdVenta DESC");return View();}
 [HttpGet]public IActionResult Crear(){ViewBag.Items=db.List("SELECT v.IdVariante,p.Nombre+' / '+v.Talla+' / '+v.Color+' / '+v.SKU AS Nombre,v.StockActual,p.PrecioVenta FROM ProductoVariante v JOIN Producto p ON p.IdProducto=v.IdProducto WHERE v.Activo=1 AND p.Activo=1 ORDER BY p.Nombre");ViewBag.Metodos=db.List("SELECT * FROM MetodoPago ORDER BY IdMetodoPago");ViewBag.Clientes=db.List("SELECT IdCliente,Nombres+' '+COALESCE(Apellidos,'') AS Nombre FROM Cliente WHERE Activo=1 ORDER BY Nombres");return View();}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult Crear(SaleForm form){try{int id=svc.Sale(form,U);TempData["ok"]="Venta #"+id+" completada y stock actualizado.";return RedirectToAction("Ticket",new{id});}catch(Exception ex){TempData["err"]=ex.Message;return RedirectToAction("Crear");}}
 public IActionResult Ticket(int id){ViewBag.Head=db.List("SELECT v.*,mp.Nombre AS Pago,c.Nombres AS Cliente,u.NombreCompleto AS Vendedora FROM Venta v JOIN MetodoPago mp ON mp.IdMetodoPago=v.IdMetodoPago JOIN Usuario u ON u.IdUsuario=v.IdUsuario LEFT JOIN Cliente c ON c.IdCliente=v.IdCliente WHERE v.IdVenta=@id",Db.P("@id",id)).FirstOrDefault();if(ViewBag.Head==null)return NotFound();ViewBag.Items=db.List("SELECT dv.*,p.Nombre,v.Talla,v.Color,v.SKU FROM DetalleVenta dv JOIN ProductoVariante v ON v.IdVariante=dv.IdVariante JOIN Producto p ON p.IdProducto=v.IdProducto WHERE dv.IdVenta=@id",Db.P("@id",id));return View();}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult Anular(int id){if(!User.IsInRole("Administrador"))return Forbid();try{svc.CancelSale(id,U);TempData["ok"]="Venta anulada y stock restituido.";}catch(Exception ex){TempData["err"]=ex.Message;}return RedirectToAction("Index");}
}
